import{_ as o,a0 as p,w as l,s as d,ao as r,I as t,x as s,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"我正在运行的 Linux 是什么版本？ | LCTT x X-CMD","titleTemplate":false,"description":"我正在运行的 Linux 是什么版本？ | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我正在运行的 Linux 是什么版本？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我正在运行的 Linux 是什么版本？ | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180612 What version of Linux am I running","title":"我正在运行的 Linux 是什么版本？","tag":"201806","desc":""},"relativePath":"201806/20180612 What version of Linux am I running.md","filePath":"[post].md"}'),u={name:"201806/20180612 What version of Linux am I running.md"};function c(h,e,g,k,f,x){const a=p("Link");return l(),d("div",null,[e[15]||(e[15]=r(`<h1 id="我正在运行的-linux-是什么版本" tabindex="-1">我正在运行的 Linux 是什么版本？ <a class="header-anchor" href="#我正在运行的-linux-是什么版本" aria-label="Permalink to “我正在运行的 Linux 是什么版本？”">​</a></h1><blockquote><p>掌握这些快捷命令以找出你正在运行的 Linux 系统的内核版本和发行版。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/yearbook-haff-rx-linux-file-lead_0.png?itok=-i0NNfDC" alt=""></p><p>“什么版本的 Linux ？”这个问题可能意味着两个不同的东西。严格地说，Linux 是内核，所以问题可以特指内核的版本号，或者 “Linux” 可以更通俗地用来指整个发行版，就像在 Fedora Linux 或 Ubuntu Linux 中一样。</p><p>两者都很重要，你可能需要知道其中一个或全部答案来修复系统中的问题。例如，了解已安装的内核版本可能有助于诊断带有专有驱动程序的问题，并且确定正在运行的发行版将帮助你快速确定是否应该使用 <code>apt</code>、 <code>dnf</code>、 <code>yum</code> 或其他命令来安装软件包。</p><p>以下内容将帮助你了解 Linux 内核的版本和/或系统上正在运行的 Linux 发行版是什么。</p><h3 id="如何找到-linux-内核版本" tabindex="-1">如何找到 Linux 内核版本 <a class="header-anchor" href="#如何找到-linux-内核版本" aria-label="Permalink to “如何找到 Linux 内核版本”">​</a></h3><p>要找出哪个 Linux 内核版本正在运行，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname -srm</span></span></code></pre></div><p>或者，可以使用更长，更具描述性的各种标志的版本来运行该命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname --kernel-name --kernel-release --machine</span></span></code></pre></div><p>无论哪种方式，输出都应该类似于以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux 4.16.10-300.fc28.x86_64 x86_64</span></span></code></pre></div><p>这为你提供了（按顺序）：内核名称、内核版本以及运行内核的硬件类型。在上面的情况下，内核是 Linux ，版本 4.16.10-300.fc28.x86_64 ，运行于 x86_64 系统。</p><p>有关 <code>uname</code> 命令的更多信息可以通过运行 <code>man uname</code> 找到。</p><h3 id="如何找出-linux-发行版" tabindex="-1">如何找出 Linux 发行版 <a class="header-anchor" href="#如何找出-linux-发行版" aria-label="Permalink to “如何找出 Linux 发行版”">​</a></h3><p>有几种方法可以确定系统上运行的是哪个发行版，但最快的方法是检查 <code>/etc/os-release</code> 文件的内容。此文件提供有关发行版的信息，包括但不限于发行版名称及其版本号。某些发行版的 <code>os-release</code> 文件包含比其他发行版更多的细节，但任何包含 <code>os-release</code> 文件的发行版都应该提供发行版的名称和版本。</p><p>要查看 <code>os-release</code> 文件的内容，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/os-release</span></span></code></pre></div><p>在 Fedora 28 中，输出如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME=Fedora</span></span>
<span class="line"><span>VERSION=&quot;28 (Workstation Edition)&quot;</span></span>
<span class="line"><span>ID=fedora</span></span>
<span class="line"><span>VERSION_ID=28</span></span>
<span class="line"><span>PLATFORM_ID=&quot;platform:f28&quot;</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Fedora 28 (Workstation Edition)&quot;</span></span>
<span class="line"><span>ANSI_COLOR=&quot;0;34&quot;</span></span>
<span class="line"><span>CPE_NAME=&quot;cpe:/o:fedoraproject:fedora:28&quot;</span></span>
<span class="line"><span>HOME_URL=&quot;https://fedoraproject.org/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://fedoraproject.org/wiki/Communicating_and_getting_help&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugzilla.redhat.com/&quot;</span></span>
<span class="line"><span>REDHAT_BUGZILLA_PRODUCT=&quot;Fedora&quot;</span></span>
<span class="line"><span>REDHAT_BUGZILLA_PRODUCT_VERSION=28</span></span>
<span class="line"><span>REDHAT_SUPPORT_PRODUCT=&quot;Fedora&quot;</span></span>
<span class="line"><span>REDHAT_SUPPORT_PRODUCT_VERSION=28</span></span>
<span class="line"><span>PRIVACY_POLICY_URL=&quot;https://fedoraproject.org/wiki/Legal:PrivacyPolicy&quot;</span></span>
<span class="line"><span>VARIANT=&quot;Workstation Edition&quot;</span></span>
<span class="line"><span>VARIANT_ID=workstation</span></span></code></pre></div><p>如上面那个例子展示的那样，Fedora 的 <code>os-release</code> 文件提供了发行版的名称和版本，但它也标识这个安装的变体（“Workstation Edition”）。如果我们在 Fedora 28 服务器版本上运行相同的命令，<code>os-release</code> 文件的内容会反映在 <code>VARIANT</code> 和 <code>VARIANT_ID</code> 行中。</p><p>有时候知道一个发行版是否与另一个发行版相似非常有用，因此 <code>os-release</code> 文件可以包含一个 <code>ID_LIKE</code> 行，用于标识正在运行的是基于什么的发行版或类似的发行版。例如，Red Hat Linux 企业版的 <code>os-release</code> 文件包含 <code>ID_LIKE</code> 行，声明 RHEL 与 Fedora 类似；CentOS 的 <code>os-release</code> 文件声明 CentOS 与 RHEL 和 Fedora 类似。如果你正在使用基于另一个发行版的发行版并需要查找解决问题的说明，那么 <code>ID_LIKE</code> 行非常有用。</p><p>CentOS 的 <code>os-release</code> 文件清楚地表明它就像 RHEL 一样，所以在各种论坛中关于 RHEL 的文档，问题和答案应该（大多数情况下）适用于 CentOS。CentOS 被设计成一个 RHEL 近亲，因此在某些字段它更兼容其 <code>ID_LIKE</code> 系统的字段。如果你找不到正在运行的发行版的信息，检查有关 “类似” 发行版的答案总是一个好主意。</p><p>有关 <code>os-release</code> 文件的更多信息可以通过运行 <code>man os-release</code> 命令来查找。</p><hr>`,26)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),n(a,{href:"https://opensource.com/article/18/6/linux-version"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/18/6/linux-version",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),n(a,{href:"https://opensource.com/users/holmja"},{default:i(()=>[...e[2]||(e[2]=[s("Joshua Allen Holm",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),n(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...e[4]||(e[4]=[s("MjSeven",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const _=o(u,[["render",c]]);export{b as __pageData,_ as default};
